/* 聊天三级记忆设置 */
.chat-settings-page .chat-memory-settings { margin-bottom:17px; padding:14px; border:1px solid rgba(0,0,0,.08); border-radius:16px; background:rgba(255,255,255,.72); }
.chat-memory-settings-head { display:flex; align-items:center; justify-content:space-between; width:100%; padding:0; border:0; background:transparent; color:#222; font:inherit; text-align:left; cursor:pointer; }
.chat-memory-settings-head > span { display:grid; gap:4px; }
.chat-memory-settings-head b { font-size:13px; font-weight:650; }
.chat-memory-settings-head small { color:#999; font-size:10px; }
.chat-memory-settings-head i { color:#888; font-size:17px; font-style:normal; }
.chat-memory-settings-body { display:grid; gap:13px; margin-top:13px; padding-top:13px; border-top:1px solid rgba(0,0,0,.07); }
.chat-memory-switch { display:flex; align-items:center; gap:10px; }
.chat-memory-switch input { width:17px; height:17px; margin:0; accent-color:#71627f; }
.chat-memory-switch > span { display:grid; flex:1; gap:3px; }
.chat-memory-switch b { font-size:11px; font-weight:600; }
.chat-memory-switch small { color:#999; font-size:9px; line-height:1.45; }
.chat-memory-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:9px; }
.chat-memory-grid > label { display:grid; gap:5px; padding:10px; border:1px solid rgba(0,0,0,.07); border-radius:12px; background:rgba(247,247,248,.82); color:#555; font-size:10px; }
.chat-memory-grid input { width:100%; height:32px; padding:0 9px; border:1px solid rgba(0,0,0,.1); border-radius:9px; outline:0; background:#fff; color:#222; font:inherit; font-size:12px; }
.chat-memory-grid small { min-height:25px; color:#999; font-size:8px; line-height:1.45; }
.chat-memory-status { display:flex; flex-wrap:wrap; gap:6px; }
.chat-memory-status span { padding:5px 7px; border-radius:8px; background:#f0edf3; color:#74667e; font-size:8px; }
.chat-memory-actions { display:flex; justify-content:flex-end; gap:8px; }
.chat-memory-actions button { min-height:34px; padding:0 13px; border:1px solid rgba(0,0,0,.1); border-radius:10px; background:#fff; color:#555; font:inherit; font-size:10px; cursor:pointer; }
.chat-memory-actions button.is-primary { border-color:#6e607a; background:#6e607a; color:#fff; }
.chat-memory-actions button:disabled { opacity:.55; }
.chat-settings-page .chat-thought-settings { padding:14px; }
.chat-thought-settings .chat-memory-settings-body { gap:15px; }
.chat-thought-api-setting { display:grid; gap:7px; color:#333; font-size:11px; }
.chat-thought-api-setting > span { display:grid; gap:3px; font-weight:600; }
.chat-thought-api-setting small { color:#999; font-size:9px; font-weight:400; line-height:1.45; }
.chat-thought-api-setting select { width:100%; min-width:0; height:37px; padding:0 11px; border:1px solid rgba(0,0,0,.1); border-radius:10px; background:#fff; color:#333; font:inherit; font-size:11px; }
.chat-thought-api-setting select:disabled { opacity:.5; }

/* 记忆库中的当前核心记忆 */
.memory-core-card { margin:0 0 16px; padding:16px; border:1px solid rgba(123,100,153,.13); border-radius:18px; background:linear-gradient(145deg,rgba(255,255,255,.76),rgba(239,233,245,.7)); box-shadow:0 8px 20px rgba(92,74,114,.05); }
.memory-core-card header { display:flex; align-items:center; justify-content:space-between; gap:10px; }
.memory-core-card header span { color:#927ca5; font-size:8px; font-weight:750; letter-spacing:.16em; }
.memory-core-card header b { color:#51445d; font-size:10px; }
.memory-core-card > p { margin-top:10px; color:#62566c; font-size:10px; line-height:1.75; white-space:pre-wrap; }
.memory-core-card > small { display:block; margin-top:11px; color:#a094aa; font-size:8px; }
.memory-core-card.is-empty { border-style:dashed; background:rgba(255,255,255,.42); }

@media (prefers-color-scheme:dark) {
  .chat-settings-page .chat-memory-settings { border-color:rgba(255,255,255,.13); background:rgba(255,255,255,.07); }
  .chat-memory-settings-head { color:#eee; }
  .chat-memory-settings-body { border-color:rgba(255,255,255,.12); }
  .chat-memory-grid > label { border-color:rgba(255,255,255,.1); background:rgba(255,255,255,.05); color:#ddd; }
  .chat-memory-grid input,.chat-memory-actions button { border-color:rgba(255,255,255,.13); background:#2b2b2b; color:#eee; }
  .chat-memory-status span { background:rgba(184,157,205,.14); color:#c9b9d5; }
  .chat-memory-actions button.is-primary { background:#8d76a0; color:#fff; }
  .chat-thought-api-setting { color:#eee; }
  .chat-thought-api-setting select { border-color:rgba(255,255,255,.13); background:#2b2b2b; color:#eee; }
  .memory-core-card { border-color:rgba(255,255,255,.12); background:linear-gradient(145deg,rgba(255,255,255,.09),rgba(127,98,149,.08)); }
  .memory-core-card header b,.memory-core-card > p { color:#e3d9e9; }
}


@media (max-width:430px) {
  .chat-memory-grid { grid-template-columns:1fr 1fr; }
  .memory-hero { gap:10px; padding:17px 14px; }
  .memory-hero dl { gap:9px; }
}

/* 自定义桌面图标使用独立图片层，避免相册默认渐变覆盖图片。 */
.app-icon,
.dock-icon { position:relative; }
.app-icon > .default-app-icon,
.dock-icon > .default-app-icon,
.folder-app-icon > .default-app-icon,
.beauty-app-preview > .default-app-icon { display:block; width:100%; height:100%; border-radius:inherit; object-fit:cover; }
.app-icon:has(> .default-app-icon),
.dock-icon:has(> .default-app-icon),
.folder-app-icon:has(> .default-app-icon) { overflow:hidden; border-color:transparent; background:none; }
.folder-mini-app > .default-app-icon { display:block; width:100%; height:100%; object-fit:cover; }
.folder-mini-app:has(> .default-app-icon)::before,
.folder-mini-app:has(> .default-app-icon)::after,
.folder-mini-app:has(> .default-app-icon) > span { display:none; }
.folder-app-icon:has(> .default-app-icon)::before,
.folder-app-icon:has(> .default-app-icon)::after,
.folder-app-icon:has(> .default-app-icon) > span { display:none; }
.app-icon.has-custom-image,
.dock-icon.has-custom-image { overflow:hidden; }
.app-icon > .app-custom-image,
.dock-icon > .app-custom-image { position:absolute !important; inset:0 !important; z-index:3 !important; display:block !important; width:100% !important; height:100% !important; border-radius:inherit; object-fit:cover !important; filter:none !important; opacity:1 !important; visibility:visible !important; mix-blend-mode:normal !important; }
.profile-card { position: relative; z-index: 1; margin: 140px 0 24px; padding: 48px 16px; border-radius: 18px; }
.person-wrap { position: relative; display: flex; align-items: center; justify-content: space-between; }
.user-item, .char-item { display: flex; align-items: center; gap: 10px; }
.love-heart { position: absolute; left: 50%; display: grid; place-items: center; width: 104px; height: 28px; color: #333; font-size: 22px; line-height: 1; transform: translateX(-50%); animation: heart-beat 1.25s ease-in-out infinite; }
.love-heart svg { position: absolute; inset: 0; width: 104px; height: 28px; overflow: visible; }
.love-heart span { position: relative; z-index: 1; }
.heartbeat-line { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 58; stroke-dashoffset: 58; animation: heartbeat-draw 1.25s linear infinite; }
@keyframes heartbeat-draw {
  0% { stroke-dashoffset: 58; opacity: .3; }
  45%, 75% { stroke-dashoffset: 0; opacity: 1; }
  100% { stroke-dashoffset: -8; opacity: .3; }
}
@keyframes heart-beat {
  0%, 100% { transform: translateX(-50%) scale(1); }
  14% { transform: translateX(-50%) scale(1.16); }
  28% { transform: translateX(-50%) scale(1); }
  42% { transform: translateX(-50%) scale(1.11); }
  56% { transform: translateX(-50%) scale(1); }
}
.avatar { width: 64px; height: 64px; flex-shrink: 0; border: 3px solid #fff; border-radius: 50%; background: var(--widget-placeholder-gray); box-shadow: 0 2px 8px rgba(0,0,0,.08); background-size: cover; background-position: center; }
.nickname-text { color: #242424; font-size: 18px; font-weight: 600; }
.sign-text { margin-top: 2px; color: #888; font-size: 13px; text-align: center; }

.page1-middle { position: relative; z-index: 1; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
.todo-widget { width: 100%; aspect-ratio: 1; padding: 14px; overflow: hidden; border-radius: 22px; }
.todo-title { margin-bottom: 8px; color: #222; font-size: 14px; font-weight: 600; }
.todo-list { max-height: calc(100% - 28px); overflow-y: auto; color: #444; font-size: 12px; }
.todo-new-row { color: #999; font-size: 12px; }
.image-widget { position:relative; width:100%; aspect-ratio:1; overflow:hidden; border-radius:22px; background-position:center; background-size:cover; background-repeat:no-repeat; cursor:pointer; }
.image-widget::after { position:absolute; inset:0; border-radius:inherit; box-shadow:inset 0 1px 0 rgba(255,255,255,.7); content:''; pointer-events:none; }
.image-widget-placeholder { position:absolute; inset:0; display:grid; place-content:center; justify-items:center; gap:8px; padding:18px; color:#777; text-align:center; transition:opacity .16s ease; }
.image-widget-placeholder svg { width:34px; height:34px; fill:none; stroke:currentColor; stroke-width:1.5; stroke-linecap:round; stroke-linejoin:round; opacity:.72; }
.image-widget-placeholder span { font-size:10px; letter-spacing:.03em; }
.image-widget.has-image .image-widget-placeholder { opacity:0; }
.countdown-widget { position:relative; width:100%; aspect-ratio:1; overflow:hidden; border-radius:22px; padding:14px; display:grid; grid-template-rows:auto 1fr auto; align-items:center; justify-items:center; text-align:center; cursor:pointer; }
.countdown-title { max-width:100%; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; margin-top:2px; color:#222; font-size:18px; font-weight:600; letter-spacing:.02em; }
.countdown-days { color:#1f1f1f; font-family:"Snell Roundhand","Bradley Hand","Segoe Print","STKaiti",cursive; font-size:60px; font-style:italic; font-weight:800; line-height:1; }
.countdown-days.is-empty, .elapsed-days.is-empty { font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",system-ui,sans-serif; font-size:17px; font-style:normal; font-weight:600; letter-spacing:0; }
.countdown-date { color:#888; font-size:14px; letter-spacing:.04em; }
.countdown-date-pickers { display:grid; grid-template-columns:1fr 1fr; gap:10px; }
.shared-widget { position:relative; display:grid; grid-template-columns:minmax(0,1.12fr) minmax(0,1fr); grid-template-rows:auto minmax(0,1fr); gap:10px 14px; width:100%; min-height:170px; padding:14px; overflow:hidden; border-radius:22px; color:#222; cursor:pointer; }
.shared-tabs { grid-column:1/-1; display:flex; align-items:center; justify-content:center; gap:20px; min-width:0; color:inherit; font-size:10px; font-weight:650; letter-spacing:.04em; }
.shared-tabs span { white-space:nowrap; }
.shared-tabs .is-active { padding:4px 10px; border-radius:11px; background:rgba(255,255,255,.46); }
.shared-images { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; min-width:0; align-self:center; }
.shared-picture { position:relative; display:grid; place-items:center; min-width:0; aspect-ratio:1; overflow:hidden; border-radius:16px; background:rgba(255,255,255,.22) center/cover no-repeat; color:inherit; }
.shared-picture::after { position:absolute; inset:0; border-radius:inherit; box-shadow:inset 0 1px 0 rgba(255,255,255,.48); content:''; pointer-events:none; }
.shared-copy { grid-column:2; grid-row:2; display:grid; grid-template-rows:minmax(0,1fr) auto; align-self:stretch; min-width:0; min-height:0; }
.shared-note { align-self:center; min-width:0; max-height:100%; margin:0; overflow:auto; color:inherit; font-size:13px; line-height:1.65; white-space:pre-wrap; overflow-wrap:anywhere; }
.shared-note:empty::before { content:'(^_^)'; opacity:.7; }
.shared-stats { display:flex; align-items:center; justify-content:flex-end; flex-wrap:wrap; gap:4px; min-width:0; margin-top:8px; color:inherit; font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",system-ui,sans-serif; font-size:10px; font-variant-numeric:normal; line-height:1.2; white-space:nowrap; }
.shared-stats span { min-width:12px; }
.shared-stats span:empty::before { content:'(^_^)'; font-size:8px; opacity:.7; }
.shared-stats b { font-weight:500; }
.shared-stats i { margin:0 2px; font-style:normal; opacity:.55; }
.chat-widget { position:relative; display:grid; gap:12px; width:100%; min-height:170px; padding:12px 10px; color:#222; cursor:pointer; }
.chat-widget-row { display:grid; align-items:center; gap:8px; min-width:0; }
.chat-widget-row.is-left { grid-template-columns:36px minmax(0,1fr) auto; }
.chat-widget-row.is-right { grid-template-columns:auto minmax(0,1fr) 36px; }
.chat-widget-row.is-left .chat-widget-bubble, .chat-widget-row.is-right .chat-widget-bubble { width:calc(100% - 36px); margin:0; box-sizing:border-box; }
.chat-widget-row.is-right .chat-widget-bubble { justify-self:end; }
.chat-widget-row.is-left time { transform:translateX(-36px); }
.chat-widget-row.is-right time { transform:translateX(36px); }
.chat-widget-avatar { width:36px; height:36px; overflow:hidden; border:1px solid rgba(255,255,255,.78); border-radius:50%; background:var(--widget-placeholder-gray) center/cover no-repeat; box-shadow:0 3px 8px rgba(0,0,0,.1), inset 0 1px 0 rgba(255,255,255,.65); }
.chat-widget-avatar:empty::before { content:none; }
.chat-widget-bubble { min-width:0; padding:10px 14px; overflow:hidden; border:1px solid rgba(255,255,255,.64); border-radius:18px; background:rgba(255,255,255,.22); box-shadow:inset 0 1px 0 rgba(255,255,255,.48),0 5px 14px rgba(0,0,0,.07); -webkit-backdrop-filter:blur(16px) saturate(135%); backdrop-filter:blur(16px) saturate(135%); }
.chat-widget-content { display:block; min-width:0; min-height:15px; overflow:hidden; color:inherit; font-size:11px; line-height:1.4; text-overflow:ellipsis; white-space:nowrap; }
.chat-widget-row.is-right .chat-widget-content { text-align:right; }
.chat-widget-content:empty::before { content:'点击编辑气泡内容'; opacity:.45; }
.chat-widget-row time { min-width:34px; color:inherit; font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:8px; line-height:1; opacity:.78; text-align:center; white-space:nowrap; }
.chat-widget-row time:empty::before { content:'时间'; opacity:.58; }
.mood-profile-widget { position:relative; display:grid; grid-template-columns:minmax(0,1fr) 86px minmax(0,1fr); align-items:center; gap:10px; width:100%; min-height:170px; padding:12px 8px; overflow:hidden; color:#222; cursor:pointer; }
.mood-profile-side { display:grid; gap:12px; min-width:0; }
.mood-profile-pill { display:flex; align-items:center; justify-content:center; min-width:0; min-height:36px; padding:0 10px; overflow:hidden; border:1px solid rgba(255,255,255,.68); border-radius:17px; background:rgba(255,255,255,.24); box-shadow:inset 0 1px 0 rgba(255,255,255,.5),0 5px 14px rgba(0,0,0,.06); text-align:center; -webkit-backdrop-filter:blur(16px) saturate(135%); backdrop-filter:blur(16px) saturate(135%); }
.mood-profile-pill span { min-width:0; overflow:hidden; color:inherit; font-size:10px; line-height:1.35; text-overflow:ellipsis; white-space:nowrap; }
.mood-profile-center { display:grid; justify-items:center; gap:8px; min-width:0; }
.mood-profile-avatar { width:78px; height:78px; overflow:hidden; border:1px solid rgba(255,255,255,.78); border-radius:50%; background:var(--widget-placeholder-gray) center/cover no-repeat; box-shadow:0 5px 15px rgba(0,0,0,.12),inset 0 1px 0 rgba(255,255,255,.62); }
.mood-profile-avatar:empty::before { content:none; }
.mood-profile-footer { max-width:100%; overflow:hidden; color:inherit; font-size:12px; line-height:1.2; text-overflow:ellipsis; white-space:nowrap; }
.time-photo-widget { position:relative; display:grid; gap:10px; width:100%; min-height:190px; padding:10px 8px; overflow:hidden; color:#222; cursor:pointer; }
.time-photo-header { display:grid; grid-template-columns:minmax(0,1fr) auto 50px; align-items:center; gap:9px; min-width:0; }
.time-photo-meta { display:flex; align-items:baseline; gap:14px; min-width:0; padding-left:8px; }
.time-photo-meta strong { overflow:hidden; font:italic 24px/1 Georgia,'Times New Roman',serif; letter-spacing:-.04em; text-overflow:ellipsis; white-space:nowrap; }
.time-photo-meta span { overflow:hidden; font:italic 17px/1 Georgia,'Times New Roman',serif; text-overflow:ellipsis; white-space:nowrap; }
.time-photo-heart { color:inherit; font-size:17px; line-height:1; }
.time-photo-avatar { width:50px; height:50px; overflow:hidden; border:1px solid rgba(255,255,255,.78); border-radius:50%; background:var(--widget-placeholder-gray) center/cover no-repeat; box-shadow:0 4px 12px rgba(0,0,0,.12),inset 0 1px 0 rgba(255,255,255,.62); }
.time-photo-avatar:empty::before { content:none; }
.time-photo-gallery { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:9px; min-width:0; padding:11px; border:1px solid rgba(255,255,255,.7); border-radius:22px; background:rgba(255,255,255,.24); box-shadow:inset 0 1px 0 rgba(255,255,255,.5),0 6px 16px rgba(0,0,0,.06); -webkit-backdrop-filter:blur(18px) saturate(135%); backdrop-filter:blur(18px) saturate(135%); }
.time-photo-image { width:100%; aspect-ratio:1 / 1; min-width:0; overflow:hidden; border:1px solid rgba(255,255,255,.72); border-radius:14px; background:var(--widget-placeholder-gray) center/cover no-repeat; }
.now-playing-widget { position:relative; display:grid; grid-template-rows:auto auto 1fr; gap:9px; width:100%; min-height:170px; padding:13px 15px; overflow:hidden; border-radius:22px; color:#222; cursor:pointer; }
.now-playing-widget::before { position:absolute; top:30px; left:32px; z-index:0; width:1px; height:26px; background:currentColor; content:''; opacity:.22; }
.now-playing-widget::after { position:absolute; top:104px; right:auto; bottom:13px; left:32px; z-index:0; width:1px; background:currentColor; content:''; opacity:.22; }
.now-playing-head { display:grid; grid-template-columns:34px minmax(0,1fr) auto 22px; align-items:center; gap:9px; min-width:0; }
.now-playing-avatar { position:relative; z-index:1; width:34px; height:34px; overflow:hidden; border:1px solid rgba(255,255,255,.78); border-radius:50%; background:var(--widget-placeholder-gray) center/cover no-repeat; box-shadow:0 3px 8px rgba(0,0,0,.1), inset 0 1px 0 rgba(255,255,255,.65); }
.now-playing-avatar:empty::before { content:none; }
.now-playing-avatar.has-image::before { content:none; }
.now-playing-head strong { min-width:0; overflow:hidden; font-size:12px; font-weight:700; text-overflow:ellipsis; white-space:nowrap; }
.now-playing-head time { color:inherit; font-size:10px; white-space:nowrap; }
.now-playing-check { display:grid; place-items:center; width:21px; height:21px; border-radius:50%; background:rgba(0,0,0,.72); color:#fff; font-size:13px; line-height:1; }
.now-playing-middle { display:grid; grid-template-columns:34px minmax(0,1fr); align-items:center; gap:9px; min-width:0; }
.now-playing-rail { position:relative; z-index:1; display:grid; place-items:center; height:53px; }
.now-playing-rail::before { display:none; }
.now-playing-rail i { position:relative; z-index:1; display:grid; place-items:center; width:29px; height:29px; border:1px solid rgba(255,255,255,.72); border-radius:50%; background:rgba(255,255,255,.52); color:inherit; font-size:15px; font-style:normal; line-height:1; }
.now-playing-rail i.is-cutlery { width:29px; height:53px; border-radius:15px; background:#fff; }
.now-playing-rail svg { width:17px; height:17px; fill:none; stroke:currentColor; stroke-linecap:round; stroke-linejoin:round; stroke-width:1.7; }
.now-playing-details { display:grid; gap:5px; min-width:0; }
.now-playing-weather { display:flex; align-items:center; gap:8px; min-width:0; color:inherit; font-size:11px; }
.now-playing-weather span:first-child { font-weight:700; }
.now-playing-weather span:last-child { opacity:.78; }
.now-playing-details > strong { min-width:0; overflow:hidden; font-size:14px; font-weight:750; text-overflow:ellipsis; white-space:nowrap; }
.now-playing-images { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); align-items:start; gap:9px; min-width:0; margin-left:43px; }
.now-image { position:relative; display:grid; place-items:center; align-self:start; width:100%; height:auto; aspect-ratio:1 / 1; min-width:0; min-height:0; overflow:hidden; border:1px solid rgba(255,255,255,.7); border-radius:12px; background-color:var(--widget-placeholder-gray); background-position:center; background-size:cover; background-repeat:no-repeat; color:rgba(75,105,130,.72); }
.now-image span { display:none; }
.now-image.is-drop, .now-image.is-rain, .now-image.is-house { background-color:var(--widget-placeholder-gray); }
.now-image.has-image > span { opacity:0; }
@media (max-width:390px) { .countdown-title { font-size:16px; } .countdown-days { font-size:54px; } .countdown-date { font-size:12px; } }
.elapsed-days-widget { position:relative; width:100%; aspect-ratio:1; overflow:hidden; border-radius:22px; padding:14px; display:grid; grid-template-rows:auto 1fr auto; align-items:center; justify-items:center; text-align:center; cursor:pointer; }
.elapsed-title { max-width:100%; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; min-height:22px; margin-top:2px; color:#222; font-size:17px; font-weight:600; letter-spacing:.02em; }
.elapsed-title:empty::before { content:'(^_^)'; color:#888; font-size:12px; font-weight:500; }
.elapsed-days { color:#1f1f1f; font-family:"Snell Roundhand","Bradley Hand","Segoe Print","STKaiti",cursive; font-size:48px; font-style:italic; font-weight:800; line-height:1; }
.elapsed-date { color:#888; font-size:13px; letter-spacing:.04em; }
.page1-apps-grid { display: grid; grid-template: repeat(2, 1fr) / repeat(2, 1fr); gap: 12px; transform: translateY(12px); }
