@media (prefers-color-scheme: dark) { .forum-app { background: #202020; color: #eee; }.forum-header { border-color: rgba(255,255,255,.12); background: rgba(28,28,28,.9); }.forum-header-actions > button { background: rgba(255,255,255,.1); color: #ddd; }.forum-header-actions > button:first-child, .forum-post-avatar, .forum-profile-avatar-preview { background: #444; color: #ddd; }.forum-feed-intro, .forum-post, .forum-role-selector { border-color: rgba(255,255,255,.12); }.forum-feed-intro p, .forum-post-body header span, .forum-post time, .forum-post-style, .forum-post-body footer button { color: #aaa; }.forum-post-text { color: #eee; }.forum-post-body footer button:hover, .forum-post-body footer button.is-liked { color: #fff; }.forum-tabs { border-color: rgba(255,255,255,.16); background: rgba(35,35,35,.72); box-shadow: 0 8px 25px rgba(0,0,0,.3), inset 0 1px 0 rgba(255,255,255,.12); }.forum-tabs > button.is-active { color: #eee; }.forum-tabs .forum-tab-compose { background: #eee; color: #111; }.forum-compose-card, .forum-profile-card { border-color: rgba(255,255,255,.14); background: rgba(35,35,35,.97); }.forum-compose-card header button, .forum-profile-card header button { background: #4a4a4d; color: #eee; }.forum-compose-card textarea, .forum-profile-card input:not([type="file"]), .forum-profile-card textarea, .forum-search-box input { border-color: rgba(255,255,255,.14); background: rgba(0,0,0,.22); color: #eee; }.forum-file-label { border-color: rgba(255,255,255,.14); background: rgba(255,255,255,.08); color: #ddd !important; }.forum-role-option { border-color: rgba(255,255,255,.13); background: rgba(255,255,255,.07); }.forum-role-option b { color: #ddd; }.forum-role-toggle { border-color: rgba(255,255,255,.2); background: rgba(255,255,255,.08); color: #ddd; }.forum-role-toggle.is-selected { border-color: #eee; background: #eee; color: #111; }.forum-compose-card footer button, .forum-profile-card footer button { background: rgba(255,255,255,.1); color: #eee; }.forum-compose-card footer button:last-child, .forum-profile-card footer .is-primary { background: #eee; color: #111; }.forum-profile-card footer .forum-profile-delete { color: #e6a0a0; }.forum-empty h2 { color: #ddd; } }
.chat-reading-head-actions .chat-reading-action-icon { display: block; width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 2.1; stroke-linecap: round; stroke-linejoin: round; }
