.chat-offline-card.is-fullscreen .chat-offline-atmosphere { margin-top:0; }.chat-offline-card.is-fullscreen .chat-offline-messages { flex:1; min-height:100px; }.chat-offline-card.is-fullscreen .chat-offline-actions { margin-top:auto; }
.chat-offline-modal.is-fullscreen-modal { padding:0; }.chat-offline-settings-button { width:30px !important; height:30px !important; margin-left:auto; margin-right:7px; border:0; border-radius:50%; background:rgba(255,255,255,.72) !important; color:#806a90 !important; font-size:15px !important; cursor:pointer; }.chat-offline-settings-panel { display:grid; gap:9px; margin:0 18px 10px; padding:12px; border:1px solid rgba(126,99,155,.13); border-radius:15px; background:rgba(255,255,255,.62); }.chat-offline-settings-panel[hidden] { display:none; }.chat-offline-settings-title { display:flex; align-items:baseline; justify-content:space-between; margin-bottom:1px; }.chat-offline-settings-title span { color:#705783; font-size:11px; font-weight:600; }.chat-offline-settings-title small { color:#ad9db7; font-size:9px; }.chat-offline-settings-panel label { display:grid; align-items:stretch; gap:9px; width:100%; min-width:0; color:#796582; font-size:10px; }.chat-offline-settings-panel select { box-sizing:border-box; display:block; width:100%; min-width:0; max-width:none; padding:5px 7px; border:1px solid rgba(126,99,155,.18); border-radius:8px; background:#fff; color:#675273; font:inherit; font-size:10px; outline:0; }
.chat-offline-preset-label { display:grid !important; align-items:stretch !important; gap:6px; width:100%; }.chat-offline-preset-label textarea { display:block; width:100%; min-width:0; min-height:120px; resize:vertical; box-sizing:border-box; padding:10px 11px; border:1px solid rgba(126,99,155,.18); border-radius:10px; background:rgba(255,255,255,.82); color:#675273; font:inherit; font-size:10px; line-height:1.5; outline:0; }.chat-offline-preset-label textarea:focus { border-color:#9d7bb5; box-shadow:0 0 0 3px rgba(157,123,181,.12); }.chat-offline-settings-panel { width:100%; box-sizing:border-box; margin-left:0; margin-right:0; }.chat-offline-settings-panel label > input[type="number"] { display:block; width:100%; min-width:0; max-width:none; box-sizing:border-box; padding:5px 7px; border:1px solid rgba(126,99,155,.18); border-radius:8px; background:#fff; color:#675273; font:inherit; font-size:10px; outline:0; }
.chat-offline-card.is-fullscreen form { display:flex; align-items:center; gap:7px; margin:0 12px 12px; padding:7px 7px 7px 13px; border:1px solid rgba(126,99,155,.16); border-radius:18px; background:rgba(255,255,255,.72); box-shadow:0 8px 22px rgba(104,78,127,.1); }.chat-offline-card.is-fullscreen form:focus-within { border-color:#a582bc; box-shadow:0 8px 24px rgba(104,78,127,.16),0 0 0 3px rgba(165,130,188,.1); }.chat-offline-card.is-fullscreen form input { flex:1; min-width:0; height:35px; padding:0; border:0; background:transparent; color:#53415f; font-size:11px; }.chat-offline-card.is-fullscreen form input::placeholder { color:#ad9eb4; }.chat-offline-card.is-fullscreen form button { flex:0 0 auto; width:42px; height:32px; border:0; border-radius:12px; background:linear-gradient(135deg,#9f7ab8,#72548c); color:#fff; font-size:0; box-shadow:0 4px 10px rgba(114,84,140,.22); }.chat-offline-card.is-fullscreen form button[type="submit"]::before { content:''; display:block; width:8px; height:8px; margin:0 auto 2px; border-top:2px solid #fff; border-right:2px solid #fff; transform:rotate(-45deg); }.chat-offline-card.is-fullscreen form .chat-offline-reply-button { width:55px; background:rgba(126,99,155,.13); color:#76598b; font-size:10px; box-shadow:none; }.chat-offline-card.is-fullscreen form .chat-offline-reply-button::before { content:none; }
.chat-offline-settings-panel .chat-offline-preset-wide { display:block; grid-column:1 / -1; width:100% !important; min-width:100% !important; max-width:none !important; box-sizing:border-box; color:#796582; font-size:10px; }.chat-offline-preset-wide > span { display:block; margin-bottom:7px; }.chat-offline-settings-panel .chat-offline-preset-wide textarea { display:block !important; width:100% !important; min-width:100% !important; max-width:none !important; height:132px; min-height:132px; box-sizing:border-box !important; margin:0; padding:11px 12px; border:1px solid rgba(126,99,155,.18); border-radius:11px; background:#fff; color:#675273; font:inherit; font-size:11px; line-height:1.55; resize:vertical; outline:0; }
.chat-offline-finish-button { align-self:center; min-height:32px; margin:8px 0 4px; padding:0 16px; border:1px solid rgba(115,82,137,.16); border-radius:16px; background:rgba(255,255,255,.52); color:#826b91; font:inherit; font-size:10px; cursor:pointer; }.chat-offline-finish-button:disabled { opacity:.55; cursor:default; }.chat-offline-summary { display:flex; align-items:center; justify-content:center; padding:calc(max(24px,env(safe-area-inset-top)) + 16px) 26px max(24px,env(safe-area-inset-bottom)); text-align:center; }.chat-offline-summary header { display:grid; justify-items:center; gap:7px; }.chat-offline-summary header h2 { font-size:22px; }.chat-offline-summary-mark { display:grid; place-items:center; width:58px; height:58px; margin:27px 0 18px; border-radius:50%; background:linear-gradient(135deg,#b89aca,#7b5c92); color:#fff; font-size:24px; box-shadow:0 12px 28px rgba(112,82,136,.22); }.chat-offline-summary > p { max-width:520px; color:#5f5067; font-size:12px; line-height:1.85; }.chat-offline-summary dl { width:min(100%,420px); margin:24px 0; padding:12px 15px; border-radius:15px; background:rgba(255,255,255,.58); }.chat-offline-summary dl div { display:flex; justify-content:space-between; gap:14px; padding:7px 0; color:#8a7895; font-size:10px; }.chat-offline-summary dt,.chat-offline-summary dd { margin:0; }.chat-offline-summary dd { color:#5f5067; }.chat-offline-summary > button { min-width:132px; height:40px; border:0; border-radius:14px; background:linear-gradient(135deg,#9672ad,#72548c); color:#fff; font:inherit; font-size:11px; cursor:pointer; }

/* 第一页的世界入口：保留记忆库和创作文件夹。 */
.page1-launch-row { grid-column:1 / -1; grid-row:2; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); align-items:start; margin-top:2px; }
