.page1-launch-row .page1-memory-launch .app-name { width:auto; transform:none; }
.page1-launch-row .page1-creative-folder { grid-column:2; transform:translateX(5px); }

/* 桌面文件夹：保持第一屏布局不变，只占用“家”右侧原本空着的第四格。 */
.desktop-folder-icon { display:grid; grid-template:repeat(3,15px)/repeat(3,15px); place-items:center; place-content:center; width:62px; min-width:62px; height:62px; gap:3px; padding:5px; overflow:hidden; border-radius:20px; border-color:rgba(255,255,255,.72); background:rgba(255,255,255,.26); -webkit-backdrop-filter:blur(22px) saturate(155%); backdrop-filter:blur(22px) saturate(155%); }
