.magazine-reader { padding:20px 18px 60px; }.magazine-reader > .magazine-cover { width:min(92%,430px); margin:0 auto 24px; }.magazine-toc,.magazine-reading-page { margin-top:13px; padding:22px; border-radius:20px; background:rgba(255,255,255,.62); }.magazine-toc ol { margin-top:16px; list-style:none; }.magazine-toc li { display:grid; grid-template-columns:25px minmax(0,1fr) auto; gap:9px; padding:9px 0; border-top:1px solid rgba(60,49,39,.09); }.magazine-toc li span { color:#a17453; font:italic 9px Georgia,serif; }.magazine-toc li b { font-size:10px; }.magazine-toc li small { color:#9c9389; font-size:7px; }.magazine-reading-page header > span { color:#a17453; font-size:8px; font-weight:700; letter-spacing:.15em; }.magazine-reading-page h2 { margin-top:8px; font-family:"Songti SC","Noto Serif CJK SC",serif; font-size:24px; line-height:1.25; }.magazine-reading-page header p { margin-top:8px; color:#887f75; font-size:10px; line-height:1.55; }.magazine-reading-page > div { margin-top:18px; font-family:"Songti SC","Noto Serif CJK SC",serif; font-size:11px; line-height:2; }
@media (max-width:600px) { .magazine-main { padding-right:14px; padding-left:14px; }.magazine-form-grid,.magazine-overview > div { grid-template-columns:1fr; gap:0; }.magazine-section-card { grid-template-columns:20px minmax(0,1fr); }.magazine-section-card aside { grid-column:2; grid-template-columns:repeat(3,1fr); align-items:center; }.magazine-interview-layout { grid-template-columns:1fr; }.magazine-interview-roles { display:flex; overflow-x:auto; }.magazine-interview-roles button { flex:0 0 112px; }.magazine-design-layout { grid-template-columns:1fr; }.magazine-cover-stage { padding:19px 36px; }.magazine-role-grid { grid-template-columns:1fr 1fr; } }
