/* 星月玻璃标本：不承载信息，只作为桌面氛围装饰。 */
.celestial-specimen-widget { position:relative; width:100%; min-height:180px; overflow:hidden; border:1px solid rgba(255,255,255,.76); border-radius:24px; background:radial-gradient(circle at 68% 42%,rgba(255,255,255,.56),transparent 29%),linear-gradient(135deg,rgba(255,255,255,.58),rgba(218,222,225,.32) 54%,rgba(255,255,255,.2)); color:#34363a; box-shadow:0 10px 28px rgba(39,43,50,.1),inset 0 1px 0 rgba(255,255,255,.78); -webkit-backdrop-filter:blur(24px) saturate(120%); backdrop-filter:blur(24px) saturate(120%); isolation:isolate; }
.celestial-specimen-widget::before { position:absolute; inset:0; z-index:-1; background-image:linear-gradient(rgba(40,44,50,.032) 1px,transparent 1px),linear-gradient(90deg,rgba(40,44,50,.026) 1px,transparent 1px); background-position:0 0; background-size:18px 18px; content:''; mask-image:linear-gradient(90deg,#000,transparent 78%); -webkit-mask-image:linear-gradient(90deg,#000,transparent 78%); animation:celestialGridDrift 24s linear infinite; }
.celestial-specimen-widget::after { position:absolute; top:-44px; right:-26px; width:174px; height:174px; border:1px solid rgba(55,59,66,.09); border-radius:50%; content:''; box-shadow:0 0 0 22px rgba(255,255,255,.06),0 0 0 23px rgba(55,59,66,.05); animation:celestialHaloBreath 8s ease-in-out infinite; }
.celestial-specimen-number { position:absolute; top:13px; left:15px; font:600 7px/1 ui-monospace,SFMono-Regular,Menlo,monospace; letter-spacing:.16em; opacity:.56; }
.celestial-specimen-copy { position:absolute; top:35px; left:15px; z-index:2; display:grid; gap:5px; width:112px; }
.celestial-specimen-copy small { font:600 6px/1.2 ui-monospace,SFMono-Regular,Menlo,monospace; letter-spacing:.17em; opacity:.52; }
.celestial-specimen-copy strong { font:italic 24px/.84 Georgia,'Times New Roman',serif; font-weight:400; letter-spacing:-.055em; }
.celestial-specimen-copy i { width:96px; margin-top:5px; padding-top:7px; border-top:1px solid rgba(52,54,58,.22); font:italic 7px/1.3 Georgia,'Times New Roman',serif; letter-spacing:.025em; opacity:.62; }
.celestial-specimen-orbit { position:absolute; top:18px; left:52%; z-index:1; width:126px; height:126px; transform:translateX(-26%) rotate(0deg); transform-origin:center; border:1px solid rgba(44,48,54,.18); border-radius:50%; animation:celestialOrbitTurn 26s linear infinite; }
.celestial-specimen-orbit::before,.celestial-specimen-orbit::after { position:absolute; top:50%; left:50%; border:1px solid rgba(44,48,54,.13); border-radius:50%; content:''; }
.celestial-specimen-orbit::before { width:145px; height:57px; transform:translate(-50%,-50%) rotate(-18deg); }
.celestial-specimen-orbit::after { width:92px; height:134px; transform:translate(-50%,-50%) rotate(38deg); }
.celestial-specimen-moon { position:absolute; top:50%; left:50%; z-index:2; width:72px; height:72px; transform:translate(-50%,-50%); overflow:hidden; border:1px solid rgba(255,255,255,.86); border-radius:50%; background:radial-gradient(circle at 34% 28%,rgba(255,255,255,.96) 0 5%,transparent 6%),radial-gradient(circle at 66% 68%,rgba(100,107,116,.12) 0 8%,transparent 9%),radial-gradient(circle at 39% 62%,rgba(96,103,112,.1) 0 6%,transparent 7%),linear-gradient(145deg,#f7f7f4,#cfd3d6); box-shadow:0 9px 25px rgba(54,60,68,.17),inset -12px -10px 18px rgba(65,72,82,.1),inset 7px 7px 12px rgba(255,255,255,.76); animation:celestialMoonFloat 6s ease-in-out infinite; }
.celestial-specimen-moon::before { position:absolute; top:15px; right:13px; width:13px; height:13px; border-radius:50%; background:rgba(96,103,112,.1); box-shadow:-25px 14px 0 -3px rgba(96,103,112,.1),-5px 32px 0 -4px rgba(96,103,112,.12); content:''; }
.celestial-specimen-moon i { position:absolute; inset:7px; border:1px solid rgba(255,255,255,.38); border-radius:50%; }
.celestial-specimen-moon b { position:absolute; right:-14px; bottom:-9px; width:54px; height:54px; border-radius:50%; background:rgba(117,124,133,.08); filter:blur(6px); }
.celestial-star { position:absolute; z-index:4; color:#474c54; font-style:normal; line-height:1; animation:celestialStarPulse 3.2s ease-in-out infinite; }
.celestial-star.is-one { top:4px; right:10px; font-size:12px; }
.celestial-star.is-two { right:-4px; bottom:32px; font-size:18px; animation-delay:-1.1s; }
.celestial-star.is-three { bottom:4px; left:14px; font-size:9px; animation-delay:-2.2s; }
.celestial-specimen-botanical { position:absolute; right:-2px; bottom:-18px; z-index:3; width:91px; height:151px; fill:none; stroke:rgba(53,57,62,.42); stroke-width:1.15; stroke-linecap:round; stroke-linejoin:round; transform:rotate(7deg); transform-origin:72% 100%; animation:celestialBotanicalSway 7s ease-in-out infinite; }
.celestial-specimen-film { position:absolute; right:58px; bottom:11px; z-index:4; display:flex; gap:4px; padding:5px 6px; border:1px solid rgba(255,255,255,.7); border-radius:5px; background:rgba(246,246,242,.44); box-shadow:0 5px 13px rgba(44,49,56,.09); transform:translateY(0) rotate(-7deg); -webkit-backdrop-filter:blur(10px); backdrop-filter:blur(10px); animation:celestialFilmFloat 5.6s ease-in-out infinite; }
.celestial-specimen-film span { width:14px; height:18px; border-radius:2px; background:linear-gradient(145deg,rgba(74,79,86,.2),rgba(255,255,255,.5)); box-shadow:inset 0 0 0 1px rgba(46,50,56,.09); }
