.celestial-specimen-seal { position:absolute; right:14px; top:12px; z-index:5; display:grid; place-items:center; width:25px; height:25px; border:1px solid rgba(53,57,62,.2); border-radius:50%; font:14px/1 Georgia,serif; transform:rotate(12deg); animation:celestialSealPulse 6.5s ease-in-out infinite; }
@keyframes celestialGridDrift { to { background-position:36px 18px; } }
@keyframes celestialHaloBreath { 0%,100% { opacity:.55; transform:scale(.96); } 50% { opacity:1; transform:scale(1.04); } }
@keyframes celestialOrbitTurn { to { transform:translateX(-26%) rotate(360deg); } }
@keyframes celestialMoonFloat { 0%,100% { transform:translate(-50%,-50%); } 50% { transform:translate(-50%,calc(-50% - 3px)); } }
@keyframes celestialStarPulse { 0%,100% { opacity:.32; transform:scale(.82); } 50% { opacity:.88; transform:scale(1.08); } }
@keyframes celestialBotanicalSway { 0%,100% { transform:rotate(5deg); } 50% { transform:rotate(10deg); } }
@keyframes celestialFilmFloat { 0%,100% { transform:translateY(0) rotate(-7deg); } 50% { transform:translateY(-4px) rotate(-4deg); } }
@keyframes celestialSealPulse { 0%,100% { opacity:.62; transform:rotate(12deg) scale(.96); } 50% { opacity:1; transform:rotate(5deg) scale(1.04); } }
@media (prefers-reduced-motion:reduce) { .celestial-specimen-widget::before,.celestial-specimen-widget::after,.celestial-specimen-orbit,.celestial-specimen-moon,.celestial-star,.celestial-specimen-botanical,.celestial-specimen-film,.celestial-specimen-seal { animation:none; } }
@media (prefers-color-scheme:dark) { .celestial-specimen-widget { border-color:rgba(255,255,255,.24); background:radial-gradient(circle at 68% 42%,rgba(255,255,255,.18),transparent 29%),linear-gradient(135deg,rgba(54,57,64,.7),rgba(27,29,34,.58)); color:#f0f0ef; box-shadow:0 12px 30px rgba(0,0,0,.24),inset 0 1px 0 rgba(255,255,255,.2); }.celestial-specimen-orbit,.celestial-specimen-orbit::before,.celestial-specimen-orbit::after { border-color:rgba(255,255,255,.2); }.celestial-star { color:#fff; }.celestial-specimen-botanical { stroke:rgba(255,255,255,.46); }.celestial-specimen-copy i { border-color:rgba(255,255,255,.25); }.celestial-specimen-seal { border-color:rgba(255,255,255,.28); } }

/* 雾雨玻璃窗 */
.mist-rain-window-widget { position:relative; width:100%; min-height:180px; overflow:hidden; border:1px solid rgba(255,255,255,.28); border-radius:24px; background:linear-gradient(155deg,rgba(36,44,58,.92),rgba(72,78,91,.72)); color:#f4f4f2; box-shadow:0 12px 30px rgba(23,29,39,.22),inset 0 1px 0 rgba(255,255,255,.2); isolation:isolate; }
