.rain-glows i { position:absolute; border-radius:50%; filter:blur(13px); opacity:.76; animation:rainGlowPulse 6s ease-in-out infinite; }
.rain-glows i:nth-child(1) { right:55px; bottom:29px; width:50px; height:50px; background:#8bb5d0; }
.rain-glows i:nth-child(2) { right:118px; bottom:44px; width:38px; height:38px; background:#e7c27d; animation-delay:-2s; }
.rain-glows i:nth-child(3) { right:18px; bottom:67px; width:29px; height:29px; background:#d995a5; animation-delay:-4s; }
.rain-window-frame::before,.rain-window-frame::after { position:absolute; z-index:2; background:rgba(224,231,237,.2); content:''; box-shadow:0 0 0 1px rgba(0,0,0,.08); }
.rain-window-frame::before { top:0; bottom:0; left:48%; width:2px; }
.rain-window-frame::after { right:0; bottom:26px; left:0; height:2px; }
.rain-drops i { position:absolute; z-index:3; top:-25px; width:2px; height:21px; border-radius:50%; background:linear-gradient(transparent,rgba(255,255,255,.72)); opacity:0; animation:rainDropFall 4.8s linear infinite; }
.rain-drops i:nth-child(1) { left:9%; animation-delay:-1s; }.rain-drops i:nth-child(2) { left:21%; height:32px; animation-delay:-3.4s; }.rain-drops i:nth-child(3) { left:35%; animation-delay:-2.2s; }.rain-drops i:nth-child(4) { left:47%; height:28px; animation-delay:-4s; }.rain-drops i:nth-child(5) { left:61%; animation-delay:-.4s; }.rain-drops i:nth-child(6) { left:72%; height:35px; animation-delay:-2.8s; }.rain-drops i:nth-child(7) { left:84%; animation-delay:-1.8s; }.rain-drops i:nth-child(8) { left:94%; height:27px; animation-delay:-4.5s; }
.rain-caption { position:absolute; top:22px; left:17px; z-index:5; display:grid; gap:6px; text-shadow:0 2px 9px rgba(0,0,0,.28); }
