.rain-caption strong { font:italic 25px/1 Georgia,'Times New Roman',serif; font-weight:400; letter-spacing:-.045em; }
.rain-curtain { position:absolute; top:-15px; right:-25px; z-index:4; width:92px; height:200px; border-left:1px solid rgba(255,255,255,.16); border-radius:52% 0 0 55%; background:linear-gradient(90deg,rgba(255,255,255,.03),rgba(255,255,255,.18)); box-shadow:-10px 0 30px rgba(255,255,255,.05); transform-origin:100% 0; animation:rainCurtainSway 8s ease-in-out infinite; }
@keyframes rainDropFall { 0% { opacity:0; transform:translateY(-20px); } 16% { opacity:.8; } 82% { opacity:.45; } 100% { opacity:0; transform:translateY(220px); } }
@keyframes rainWindowHaze { 0%,100% { opacity:.55; transform:translateX(-3%); } 50% { opacity:1; transform:translateX(4%); } }
@keyframes rainGlowPulse { 0%,100% { opacity:.45; transform:scale(.9); } 50% { opacity:.85; transform:scale(1.08); } }
