/* 聊天气泡右滑引用。 */
.chat-message { touch-action: pan-y; }
.chat-message-line { transition: transform .18s ease; }
.chat-message.is-quote-tracking .chat-message-line { transition: none; }
.chat-quote-bar { position: absolute; right: 0; bottom: calc(100% + 8px); left: 0; z-index: 4; display: flex; align-items: center; gap: 10px; margin: 0; padding: 8px 10px; border-left: 3px solid #222; border-radius: 10px; background: rgba(255,255,255,.9); color: #555; box-shadow: 0 5px 16px rgba(0,0,0,.1); -webkit-backdrop-filter: blur(18px); backdrop-filter: blur(18px); }
.chat-quote-bar > div { min-width: 0; flex: 1; }
.chat-quote-bar small { display: block; color: #777; font-size: 10px; }
.chat-quote-bar p { margin-top: 3px; overflow: hidden; color: #999; font-size: 10px; line-height: 1.35; text-overflow: ellipsis; white-space: nowrap; }
.chat-quote-bar > button { flex: 0 0 auto; width: 22px; height: 22px; padding: 0; border: 0; border-radius: 50%; background: rgba(0,0,0,.07); color: #777; font-size: 16px; line-height: 1; cursor: pointer; }
.chat-message-quote { margin: -2px -2px 7px; padding: 6px 8px; border-left: 2px solid currentColor; border-radius: 6px; background: rgba(0,0,0,.07); opacity: .78; }
.chat-message-quote small { display: block; color: inherit; font-size: 9px; }
.chat-message-quote p { margin-top: 2px; overflow: hidden; color: inherit; font-size: 10px; line-height: 1.35; text-overflow: ellipsis; white-space: nowrap; }

/* 回复引用与群聊正文都要完整换行，不能被单行省略号截断。 */
.chat-message-quote p {
  overflow: visible !important;
  text-overflow: clip !important;
  white-space: pre-wrap !important;
  overflow-wrap: anywhere !important;
  word-break: break-word !important;
}
.chat-group-conversation .chat-group-bubble-row > .chat-bubble:not(.transfer):not(.location):not(.tap):not(.image):not(.image-stack):not(.image-desc) {
  overflow: visible !important;
  text-overflow: clip !important;
  white-space: pre-wrap !important;
  overflow-wrap: anywhere !important;
  word-break: break-word !important;
}
.chat-conversation.has-chat-quote .chat-messages { padding-bottom: 17px; }
.chat-conversation.has-chat-quote .chat-messages::after { content: ''; display: block; height: 58px; min-height: 58px; }
.chat-conversation.has-chat-quote .chat-messages { padding-bottom:0; }
.chat-conversation.has-chat-quote .chat-messages::after { content:none; display:none; height:0; min-height:0; }
.chat-message.is-quote-tracking .chat-message-line { will-change:transform; }
.chat-contact-card { position:relative; display:block; overflow:hidden; padding:0; touch-action:pan-y; }
.chat-contact-swipe-action { position:absolute; inset:0; display:flex; align-items:center; justify-content:flex-end; background:transparent; }
.chat-contact-pin { width:38px; height:38px; margin-right:12px; padding:0; border:0; border-radius:50%; background:#222; color:#fff; font:inherit; font-size:21px; line-height:1; opacity:0; pointer-events:none; box-shadow:0 5px 13px rgba(0,0,0,.18); cursor:pointer; transition:opacity .12s ease; }
.chat-contact-card.is-swipe-open .chat-contact-pin,
.chat-contact-card.is-swipe-revealing .chat-contact-pin { opacity:1; pointer-events:auto; }
.chat-contact-card-content { position:relative; z-index:1; display:flex !important; align-items:center; width:100%; min-height:69px; box-sizing:border-box; gap:11px; padding:13px; border-radius:inherit; background:rgba(255,255,255,.48); transition:transform .18s cubic-bezier(.22,.61,.36,1); will-change:transform; }
.chat-contact-card-content.is-swipe-tracking { transition:none; }
.chat-contact-card.is-pinned .chat-contact-card-content { border-color:rgba(34,34,34,.24); background:rgba(34,34,34,.13); }
.chat-contact-card-content > div:nth-child(2) { display:grid; flex:1; min-width:0; gap:5px; }
.chat-contact-card-content > div:nth-child(2) b { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.chat-contact-card-content > div:nth-child(2) p { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.chat-launch-contact-swipe { position:relative; overflow:hidden; margin-bottom:9px; border-radius:16px; background:rgba(255,255,255,.48); touch-action:pan-y; }
.chat-launch-contact-swipe > .chat-launch-contact { position:relative; z-index:1; margin:0; transition:transform .18s cubic-bezier(.22,.61,.36,1); will-change:transform; }
.chat-launch-contact-swipe > .chat-launch-contact.is-swipe-tracking { transition:none; }
.chat-launch-contact-swipe > .chat-launch-contact.is-pinned { border-color:rgba(34,34,34,.24); background:rgba(34,34,34,.13); }
.chat-launch-contact-pin { position:absolute; top:50%; right:12px; z-index:0; width:38px; height:38px; padding:0; transform:translateY(-50%); border:0; border-radius:50%; background:#222; color:#fff; font:inherit; font-size:21px; line-height:1; opacity:0; pointer-events:none; box-shadow:0 5px 13px rgba(0,0,0,.18); cursor:pointer; transition:opacity .12s ease; }
.chat-launch-contact-swipe.is-swipe-open .chat-launch-contact-pin,
.chat-launch-contact-swipe.is-swipe-revealing .chat-launch-contact-pin { opacity:1; pointer-events:auto; }
@media (prefers-color-scheme:dark) {
  .chat-contact-card-content { background:rgba(255,255,255,.07); }
  .chat-contact-card.is-pinned .chat-contact-card-content { border-color:rgba(255,255,255,.24); background:rgba(255,255,255,.16); }
  .chat-launch-contact-swipe { background:rgba(255,255,255,.07); }
  .chat-launch-contact-swipe > .chat-launch-contact.is-pinned { border-color:rgba(255,255,255,.24); background:rgba(255,255,255,.16); }
}
@media (prefers-color-scheme: dark) {
  .chat-quote-bar { border-left-color: #eee; background: rgba(255,255,255,.1); color: #ddd; }
  .chat-quote-bar small { color: #ccc; }
  .chat-quote-bar p { color: #aaa; }
  .chat-quote-bar > button { background: rgba(255,255,255,.12); color: #ddd; }
  .chat-message-quote { background: rgba(255,255,255,.12); }
}

/* 引用预览属于底部输入区本身：和聊天气泡一样位于消息列表下方、输入框上方，
   不再以绝对定位浮在消息内容上。这样键盘抬升时整组输入区也会一起移动。 */
.chat-app.is-chatting .chat-conversation > .chat-compose-wrap.has-chat-quote {
  display:flex !important;
  flex-direction:column !important;
  flex-basis:auto !important;
  height:auto !important;
  min-height:96px !important;
  padding-top:10px !important;
  padding-bottom:8px !important;
  overflow:visible !important;
}
.chat-app.is-chatting .chat-conversation > .chat-compose-wrap.has-chat-quote > .chat-quote-bar {
  position:relative !important;
  inset:auto !important;
  order:0 !important;
  flex:0 0 auto !important;
  width:100% !important;
  box-sizing:border-box !important;
  margin:0 0 8px !important;
}
.chat-app.is-chatting .chat-conversation > .chat-compose-wrap.has-chat-quote > .chat-compose {
  order:1 !important;
  flex:0 0 44px !important;
  height:44px !important;
  min-height:44px !important;
  transform:none !important;
}

/* 键盘抬起时输入区会向上平移，消息列表要预留同等空间，避免最后一条气泡被输入区覆盖。 */
.chat-app.is-chatting .chat-conversation > .chat-messages.is-keyboard-avoiding {
  padding-bottom:calc(var(--chat-keyboard-bottom-space, 0px) + 17px) !important;
}

/* 世界书条目正文占满卡片宽度，编辑/删除操作单独放在正文下方。 */
.worldbook-entry { display: block; }
.worldbook-entry > .worldbook-entry-copy { width: 100%; max-width: none; }
.worldbook-entry > .worldbook-entry-copy > p { width: 100%; box-sizing: border-box; padding-right: 0; scrollbar-gutter: auto; }
.worldbook-entry > .worldbook-entry-actions { justify-content: flex-end; margin-top: 12px; }
.chat-thought-actions { display: flex; justify-content: center; align-items: center; gap: 28px; margin-top: 14px; }
.chat-thought-actions button { min-width: 92px; min-height: 32px; padding: 0 14px; border: 1px solid rgba(0,0,0,.12); border-radius: 999px; background: #222; color: #fff; font: inherit; font-size: 11px; cursor: pointer; }
.chat-thought-actions button:disabled { cursor: default; opacity: .45; }
.chat-thought-actions button[data-chat-thought-prev],
.chat-thought-actions button[data-chat-thought-next] {
  min-width: 28px;
  width: 28px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: #222;
  font-size: 25px;
  line-height: 1;
}
.worldbook-entry.is-disabled .worldbook-entry-copy { opacity: .48; }
.worldbook-entry-toggle { display: inline-flex; align-items: center; gap: 5px; padding: 5px 7px !important; border: 1px solid rgba(0,0,0,.1) !important; border-radius: 999px !important; background: rgba(0,0,0,.04) !important; color: #999 !important; font-size: 10px !important; }
.worldbook-entry-toggle-track { position: relative; width: 24px; height: 14px; border-radius: 999px; background: #c8c8c4; transition: background .18s ease; }
.worldbook-entry-toggle-track i { position: absolute; top: 2px; left: 2px; width: 10px; height: 10px; border-radius: 50%; background: #fff; box-shadow: 0 1px 3px rgba(0,0,0,.18); transition: transform .18s ease; }
.worldbook-entry-toggle.is-on { border-color: #222 !important; background: #fff !important; color: #222 !important; }
.worldbook-entry-toggle.is-on .worldbook-entry-toggle-track { background: #222; }
.worldbook-entry-toggle.is-on .worldbook-entry-toggle-track i { transform: translateX(10px); }
@media (prefers-color-scheme: dark) {
  .worldbook-entry-toggle { border-color: rgba(255,255,255,.16) !important; background: rgba(255,255,255,.08) !important; color: #aaa !important; }
  .worldbook-entry-toggle-track { background: #666; }
  .worldbook-entry-toggle.is-on { border-color: #eee !important; background: rgba(255,255,255,.08) !important; color: #eee !important; }
  .worldbook-entry-toggle.is-on .worldbook-entry-toggle-track { background: #eee; }
  .worldbook-entry-toggle-track i { background: #222; }
}

/* 心声面板改为从聊天顶栏下方滑出的顶部抽屉。 */
.chat-thought { align-items: flex-start; justify-content: center; overflow-y: auto; padding: max(64px, calc(env(safe-area-inset-top) + 58px)) 12px 18px; }
.chat-thought-card { width: min(100%, 430px); transform: translateY(-18px); opacity: 0; }
.chat-thought.is-open .chat-thought-card { animation: chat-thought-slide-down .24s ease-out forwards; }
@keyframes chat-thought-slide-down { from { transform: translateY(-18px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

/* 心声只作为顶栏下方的抽屉出现，不遮暗或模糊后面的聊天内容。 */
.chat-thought-backdrop {
  background: transparent !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}
.chat-thought-card {
  display: block;
  box-sizing: border-box;
  max-height: none;
  overflow: visible;
  background: rgba(248,248,246,.58) !important;
  -webkit-backdrop-filter: blur(24px) saturate(150%);
  backdrop-filter: blur(24px) saturate(150%);
}
.chat-thought-card p {
  max-height: none;
  overflow: visible;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
  word-break: break-word;
}
.chat-tools button[data-chat-tool="reroll"] { color: #222; }
.chat-tools button[data-chat-tool="reroll"]:disabled { cursor: default; opacity: .45; }
@media (prefers-color-scheme: dark) {
  .chat-thought-card { background: rgba(32,32,32,.62) !important; border-color: rgba(255,255,255,.2); }
}
