/* 进入刊物后的四步工作流，始终告诉用户现在该做什么。 */
.magazine-process-guide {
  display:grid;
  grid-template-columns:minmax(185px,.8fr) minmax(0,1.6fr);
  align-items:center;
  gap:18px;
  margin:0 0 22px;
  padding:14px 16px;
  border:1px solid rgba(91,69,51,.1);
  border-radius:18px;
  background:rgba(255,255,255,.48);
  box-shadow:0 7px 16px rgba(73,55,39,.04);
}
.magazine-process-copy {
  display:grid;
  gap:4px;
  padding-right:14px;
  border-right:1px solid rgba(91,69,51,.1);
}
.magazine-process-copy span {
  color:#ab7653;
  font-size:7px;
  font-weight:800;
  letter-spacing:.18em;
}
.magazine-process-copy b {
  color:#49382e;
  font-family:"Songti SC","Noto Serif CJK SC",serif;
