.magazine-process-guide button {
  display:flex;
  align-items:center;
  gap:7px;
  width:100%;
  min-height:42px;
  padding:5px 6px;
  border:1px solid transparent;
  border-radius:11px;
  background:transparent;
  color:#978a80;
  font:inherit;
  text-align:left;
