/* 发布后的刊物进入只读翻页阅读器。 */
.magazine-flipbook-reader {
  display:grid;
  justify-items:center;
  gap:13px;
  min-height:calc(100% - 1px);
  padding:25px clamp(14px,4vw,34px) 54px;
  background:
    radial-gradient(circle at 18% 8%,rgba(255,255,255,.82),transparent 25%),
    linear-gradient(145deg,#eee8de,#e1d9cd);
}
.magazine-flipbook {
  width:min(100%,560px);
  perspective:1300px;
}
.magazine-flipbook-page {
  box-sizing:border-box;
  min-height:min(690px,calc(100vh - 190px));
  padding:20px;
  overflow:hidden;
  border:1px solid rgba(91,69,51,.14);
  border-radius:4px 17px 17px 4px;
  background:linear-gradient(135deg,#fffdf8,#f4eee5);
  box-shadow:12px 14px 0 -7px rgba(171,142,116,.2),0 18px 36px rgba(73,55,39,.13),inset 7px 0 rgba(112,81,58,.07),inset 0 1px rgba(255,255,255,.9);
  transform-origin:left center;
  backface-visibility:hidden;
}
.magazine-flipbook-page.from-right { animation:magazine-page-from-right .34s cubic-bezier(.22,.68,.24,1); }
.magazine-flipbook-page.from-left { animation:magazine-page-from-left .34s cubic-bezier(.22,.68,.24,1); }
@keyframes magazine-page-from-right {
  from { opacity:.25; transform:rotateY(-78deg) translateX(12px); }
  to { opacity:1; transform:rotateY(0) translateX(0); }
}
@keyframes magazine-page-from-left {
  from { opacity:.25; transform:rotateY(78deg) translateX(-12px); }
  to { opacity:1; transform:rotateY(0) translateX(0); }
}
.magazine-flip-cover {
