  .desktop-page .date-calendar-card,
  .desktop-page .dock-bar {
    -webkit-backdrop-filter:blur(10px) saturate(115%);
    backdrop-filter:blur(10px) saturate(115%);
    box-shadow:0 5px 16px rgba(0,0,0,.07),inset 0 1px 0 rgba(255,255,255,.62);
  }
  .desktop-page .app-icon,
  .desktop-page .dock-icon {
    -webkit-backdrop-filter:blur(7px) saturate(110%);
