  }
}

/* 主屏横向翻页与页面内部纵向滚动需要同时放行，不能让子页面的 pan-y 拦住外层横向滚动。 */
.desktop-scroll-wrap {
  height:calc(100dvh - 140px);
  min-height:0;
  overflow-x:auto;
  overflow-y:hidden;
  scroll-snap-type:x mandatory;
  scroll-snap-stop:always;
  touch-action:pan-x pan-y;
  -webkit-overflow-scrolling:touch;
}
.desktop-page {
  min-height:0;
  overflow-y:hidden;
  overscroll-behavior-y:none;
  touch-action:pan-x pan-y;
}
@media (max-width:680px) {
  .desktop-page {
    overflow-x:hidden;
    overflow-y:hidden;
    touch-action:pan-x pan-y;
  }
}

