.chat-group-conversation .chat-group-sender { display:flex; align-items:baseline; gap:5px; margin:0; color:#596576; font-size:11px; line-height:1.2; }
.chat-group-conversation .chat-group-sender b { padding:0; background:transparent; font-weight:750; }
.chat-group-conversation .chat-group-sender em { overflow:hidden; color:#8a95a5; font-size:9px; font-style:normal; text-overflow:ellipsis; white-space:nowrap; }
