}
.chat-group-conversation .chat-message.is-user .chat-bubble:not(.image):not(.transfer):not(.location):not(.tap):not(.image-desc):not(.image-stack) {
  border-bottom-right-radius:5px;
  background:var(--chat-user-bubble,#222);
  color:var(--chat-user-text,#fff);
