  width:100%;
  max-width:100%;
}
.ta-role-conversation .ta-chat-message:has(.ta-chat-sender-name) .ta-chat-message-content {
  display:grid;
  flex:0 1 auto;
  width:fit-content;
  min-width:0;
  max-width:calc(100% - 52px);
  gap:4px;
  justify-items:start;
}
.ta-role-conversation .ta-chat-message:has(.ta-chat-sender-name) .ta-chat-sender-name {
  width:fit-content;
  max-width:100%;
  padding:0;
  overflow:hidden;
  border-radius:0;
