.couple-paper-sheet { position:relative; z-index:2; box-sizing:border-box; width:min(100%,430px); min-height:min(430px,65vh); max-height:78vh; overflow-y:auto; overscroll-behavior:contain; padding:48px 32px 40px; clip-path:polygon(.6% 1.2%,15% .3%,32% .8%,50% 0,70% .7%,86% .2%,99% 1%,99.5% 20%,99% 43%,100% 64%,99.3% 84%,99.8% 99%,82% 99.5%,63% 99%,43% 100%,25% 99.3%,.5% 99.8%,0 78%,.7% 53%,0 30%); background:#fff url("assets/ui/couple-paper/white-crumpled-sheet.png") center / 100% 100% no-repeat; background-image:image-set(url("assets/ui/couple-paper/white-crumpled-sheet.webp") type("image/webp"),url("assets/ui/couple-paper/white-crumpled-sheet.png") type("image/png")); color:#353535; box-shadow:0 24px 56px #00000040; opacity:0; pointer-events:none; transform-origin:center; }
