  box-shadow:none;
}
.ta-reverse-page > main > .ta-reverse-caught p { color:#777078; }
.ta-reverse-page > main > .ta-reverse-caught b { color:#8d6574; }
.ta-reverse-page > main > .ta-reverse-result article {
  padding:11px 0;
  border:0;
  border-bottom:1px solid rgba(0,0,0,.1);
  border-radius:0;
  background:transparent;
}
.ta-reverse-page > main > .ta-reverse-result article:last-child { border-bottom:0; }
.ta-reverse-page > main > .ta-reverse-result > footer,
.ta-reverse-page > main > .ta-reverse-final {
  padding:12px 0;
  border:0;
  border-top:1px solid rgba(0,0,0,.1);
  border-radius:0;
  background:transparent;
}
.ta-reverse-page > main > .ta-reverse-browser,
.ta-reverse-page.is-live > main > .ta-reverse-browser {
  width:100%;
  border:0;
  border-radius:0;
  background:transparent;
  box-shadow:none;
}
.ta-reverse-page > main > .ta-reverse-browser > header { background:transparent; }
.ta-reverse-page > main > .ta-reverse-browser > main { background:transparent; }
@media (prefers-color-scheme:dark) {
  .ta-reverse-page > main > .ta-reverse-hero,
  .ta-reverse-page > main > .ta-reverse-caught,
  .ta-reverse-page > main > .ta-reverse-result article,
  .ta-reverse-page > main > .ta-reverse-result > footer,
  .ta-reverse-page > main > .ta-reverse-final { border-color:rgba(255,255,255,.14); }
  .ta-reverse-page > main > .ta-reverse-hero small,
  .ta-reverse-page > main > .ta-reverse-hero p,
  .ta-reverse-page > main > .ta-reverse-caught p { color:#b9adb4; }
  .ta-reverse-page > main > .ta-reverse-hero > button { background:#eee; color:#222; }
}

/* 钱包页保留银行卡卡片，其他 Ta 页面仍使用紧凑列表。 */
.ta-role-app-main > .ta-wallet-page .ta-wallet-balance {
  position:relative;
  isolation:isolate;
  min-height:190px;
  overflow:hidden;
  padding:24px !important;
  border:0 !important;
  border-radius:22px !important;
  background:linear-gradient(135deg,#17191f 0%,#303747 58%,#15171c 100%) !important;
  color:#fff !important;
  box-shadow:0 15px 34px rgba(20,24,32,.24) !important;
}
.ta-role-app-main > .ta-wallet-page .ta-wallet-balance::before {
  display:block;
  width:40px;
  height:29px;
  margin-bottom:15px;
  border:1px solid rgba(255,255,255,.38);
  border-radius:7px;
  background:linear-gradient(135deg,#e8d9a3,#aa9360);
  box-shadow:inset 0 0 0 5px rgba(255,255,255,.13);
  content:"";
}
.ta-role-app-main > .ta-wallet-page .ta-wallet-balance::after {
  position:absolute;
  right:22px;
  bottom:19px;
  color:rgba(255,255,255,.7);
  font:600 10px/1.2 ui-monospace,SFMono-Regular,Menlo,monospace;
  letter-spacing:.13em;
  content:attr(data-card-number);
}
.ta-role-app-main > .ta-wallet-page .ta-wallet-balance > small { color:rgba(255,255,255,.68) !important; }
.ta-role-app-main > .ta-wallet-page .ta-wallet-balance > strong { color:#fff !important; text-shadow:0 2px 8px rgba(0,0,0,.2); }
.ta-role-app-main > .ta-wallet-page .ta-wallet-balance > div { margin-bottom:25px; color:rgba(255,255,255,.78) !important; }

/* 聊天设置折叠项：把箭头区域横向放宽，但不额外绘制按钮边框。 */
.chat-memory-settings-head > i,
.chat-tap-settings-head > i,
.character-setting-head > i {
  display:grid;
  flex:0 0 52px;
  place-items:center;
  width:52px;
  min-width:52px;
  height:36px;
  box-sizing:border-box;
  color:#777;
  font-size:22px;
  line-height:1;
  transform:scaleX(1.32) scaleY(.9);
  transform-origin:center;
}
/* 互动设置卡片比外层记忆卡片多一层 18px 内缩，补回这段距离让箭头列重合。 */
.chat-interaction-settings > .chat-tap-settings > .chat-tap-settings-head > i,
.chat-interaction-settings > .character-setting-item > .character-setting-head > i {
  margin-right:-18px;
}
.chat-memory-settings-head > i { margin-right:-6px; }
.chat-translation-original,
.chat-translation-text {
  display:block;
  white-space:pre-wrap;
}
.chat-translation-original { opacity:.72; }
.chat-translation-text {
  margin-top:7px;
  padding-top:7px;
  border-top:1px solid rgba(0,0,0,.12);
}
@media (prefers-color-scheme:dark) {
  .chat-translation-text { border-color:rgba(255,255,255,.2); }
}
